&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 71&lt;/i&gt;
&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;153 600 PX&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; de taille Gig, NM&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init&lt;/b&gt; +4 ; Sens sens draconiques, vision dans les t&#233;n&#232;bres ; Perception +38&lt;/li&gt;&lt;li&gt;&lt;b&gt;Aura &lt;/b&gt;pr&#233;sence &#233;trang&#232;re (90 m, DD 29)&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;38, contact 6, pris au d&#233;pourvu 38 (naturelle +32, taille -4)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;324 (24d12+168)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+16, Vig +21, Vol +21&lt;/li&gt;&lt;li&gt;&lt;b&gt;RD &lt;/b&gt;15/magie ; &lt;b&gt;Immunit&#233;s &lt;/b&gt;confusion, effets d’ali&#233;nation mentale, froid, paralysie, sommeil ; &lt;b&gt;RM &lt;/b&gt;29&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD &lt;/b&gt;12 m, &lt;b&gt;vol &lt;/b&gt;75 m (bonne)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +33 (4d6+18/19-20 plus oblit&#233;ration) et 2 griffes, +32 (2d8+12) et 2 ailes, +30 (2d6+6) et coup de queue, +30 (2d8+18)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace &lt;/b&gt;6 m ; &lt;b&gt;Allonge &lt;/b&gt;4,50 m (6 m avec la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; balayage de la queue, &#233;crasement, oblit&#233;ration (DD 29), regard du n&#233;ant (DD 29), souffle (c&#244;ne de 18 m, 20d8 froid, DD 29), souffle suffocant (DD 29)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;b&gt;NLS&lt;/b&gt; 24 ; concentration +31)&lt;ul&gt;&lt;li&gt;&lt;i&gt;&#192; volont&#233;&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Flou.html&quot; title=&quot;Flou&quot;&gt;flou&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Porte-Dimensionnelle.html&quot; title=&quot;Porte dimensionnelle&quot;&gt;porte dimensionnelle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rayon-Affaiblissant.html&quot; title=&quot;Rayon affaiblissant&quot;&gt;rayon affaiblissant&lt;/a&gt; (DD 18), &lt;a class=&quot;pagelink&quot; href=&quot;Rayon-D&#233;puisement.html&quot; title=&quot;Rayon d&amp;#39;&#233;puisement&quot;&gt;rayon d’&#233;puisement&lt;/a&gt; (DD 20)&lt;/li&gt;&lt;li&gt;&lt;i&gt;1/jour&lt;/i&gt; — &lt;i&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Sort-Cauchemar.html&quot; title=&quot;Cauchemar&quot;&gt;cauchemar&lt;/a&gt;&lt;/i&gt; (DD 22)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts d’ensorceleur&lt;/b&gt; connus (&lt;b&gt;NLS &lt;/b&gt;15 ; concentration 22)&lt;ul&gt;&lt;li&gt;&lt;i&gt;7&#232;me (5/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Rayons-Prismatiques.html&quot; title=&quot;Rayons prismatiques&quot;&gt;rayons prismatiques&lt;/a&gt; (DD 24), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Mystique.html&quot; title=&quot;Vision mystique&quot;&gt;vision mystique&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;6&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;sint&#233;gration.html&quot; title=&quot;D&#233;sint&#233;gration&quot;&gt;d&#233;sint&#233;gration&lt;/a&gt; (DD 23), &lt;a class=&quot;pagelink&quot; href=&quot;Mauvais-Oeil.html&quot; title=&quot;Mauvais œil&quot;&gt;mauvais oeil&lt;/a&gt; (DD 23), &lt;a class=&quot;pagelink&quot; href=&quot;Travers&#233;e-Des-Ombres.html&quot; title=&quot;Travers&#233;e des ombres&quot;&gt;travers&#233;e des ombres&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;5&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Annulation-Denchantement.html&quot; title=&quot;Annulation d&amp;#39;enchantement&quot;&gt;annulation d’enchantement&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;bilit&#233;.html&quot; title=&quot;D&#233;bilit&#233;&quot;&gt;d&#233;bilit&#233;&lt;/a&gt; (DD 22), &lt;a class=&quot;pagelink&quot; href=&quot;Domination.html&quot; title=&quot;Domination&quot;&gt;domination&lt;/a&gt; (DD 22), &lt;a class=&quot;pagelink&quot; href=&quot;Renvoi.html&quot; title=&quot;Renvoi&quot;&gt;renvoi&lt;/a&gt; (DD 22)&lt;/li&gt;&lt;li&gt;&lt;i&gt;4&#232;me (7/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Ancre-Dimensionnelle.html&quot; title=&quot;Ancre dimensionnelle&quot;&gt;ancre dimensionnelle&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Charme-Monstre.html&quot; title=&quot;Charme-monstre&quot;&gt;charme-monstre&lt;/a&gt; (DD 21), &lt;a class=&quot;pagelink&quot; href=&quot;Confusion.html&quot; title=&quot;Confusion&quot;&gt;confusion&lt;/a&gt; (DD 21), &lt;a class=&quot;pagelink&quot; href=&quot;Scrutation.html&quot; title=&quot;Scrutation&quot;&gt;scrutation&lt;/a&gt; (DD 21)&lt;/li&gt;&lt;li&gt;&lt;i&gt;3&#232;me (8/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Dissipation-De-La-Magie.html&quot; title=&quot;Dissipation de la magie&quot;&gt;dissipation de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;&#201;clair.html&quot; title=&quot;&#201;clair&quot;&gt;&#233;clair&lt;/a&gt; (DD 20), &lt;a class=&quot;pagelink&quot; href=&quot;H&#233;ro&#239;sme.html&quot; title=&quot;H&#233;ro&#239;sme&quot;&gt;h&#233;ro&#239;sme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Rapidit&#233;.html&quot; title=&quot;Rapidit&#233;&quot;&gt;rapidit&#233;&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;2&#232;me (8/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Idiotie.html&quot; title=&quot;Idiotie&quot;&gt;idiotie&lt;/a&gt; (DD 19), &lt;a class=&quot;pagelink&quot; href=&quot;Invisibilit&#233;.html&quot; title=&quot;Invisibilit&#233;&quot;&gt;invisibilit&#233;&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Localisation-Dobjet.html&quot; title=&quot;Localisation d&amp;#39;objet&quot;&gt;localisation d’objet&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Partage-Des-Souvenirs.html&quot; title=&quot;Partage des souvenirs&quot;&gt;partage des souvenirs&lt;/a&gt; (DD 19), &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;sistance-Aux-&#201;nergies-Destructives.html&quot; title=&quot;R&#233;sistance aux &#233;nergies destructives&quot;&gt;r&#233;sistance aux &#233;nergies destructives&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;1er (8/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Alarme.html&quot; title=&quot;Alarme&quot;&gt;alarme&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Brume-De-Dissimulation.html&quot; title=&quot;Brume de dissimulation&quot;&gt;brume de dissimulation&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Frayeur.html&quot; title=&quot;Frayeur&quot;&gt;frayeur&lt;/a&gt; (DD 18), &lt;a class=&quot;pagelink&quot; href=&quot;Hypnose.html&quot; title=&quot;Hypnose&quot;&gt;hypnose&lt;/a&gt; (DD 18)&lt;/li&gt;&lt;li&gt;&lt;i&gt;0 (&#224; volont&#233;)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;, 6 de plus&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For &lt;/b&gt;35, &lt;b&gt;Dex &lt;/b&gt;10, &lt;b&gt;Con &lt;/b&gt;25, &lt;b&gt;Int &lt;/b&gt;24, &lt;b&gt;Sag &lt;/b&gt;21, &lt;b&gt;Cha &lt;/b&gt;24&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+24 ; &lt;b&gt;BMO &lt;/b&gt;+40 ; &lt;b&gt;DMD &lt;/b&gt;50 (54 contre croc-en-jambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (morsure), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Vol.html&quot; title=&quot;Attaque en vol&quot;&gt;Attaque en vol&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Magie-De-Guerre.html&quot; title=&quot;Magie de guerre&quot;&gt;Magie de guerre&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;R&#233;flexes-Surhumains.html&quot; title=&quot;R&#233;flexes surhumains&quot;&gt;R&#233;flexes surhumains&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Incantation-Rapide.html&quot; title=&quot;Incantation rapide&quot;&gt;Incantation rapide&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-De-Linitiative.html&quot; title=&quot;Science de l&amp;#39;initiative&quot;&gt;Science de l’initiative&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Science-Du-Critique.html&quot; title=&quot;Science du critique&quot;&gt;Science du critique&lt;/a&gt; (morsure), &lt;a class=&quot;pagelink&quot; href=&quot;Talent.html&quot; title=&quot;Talent&quot;&gt;Talent&lt;/a&gt; (Perception), &lt;a class=&quot;pagelink&quot; href=&quot;Virage-Sur-Laile.html&quot; title=&quot;Virage sur l&amp;#39;aile&quot;&gt;Virage sur l’aile&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Vol-Stationnaire.html&quot; title=&quot;Vol stationnaire&quot;&gt;Vol stationnaire&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +24, &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +34, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +34, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res, plans, religion) +34, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +15, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +25, &lt;a class=&quot;pagelink&quot; href=&quot;Estimation.html&quot; title=&quot;Estimation&quot;&gt;Estimation&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +34, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +38, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +32, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +20, &lt;a class=&quot;pagelink&quot; href=&quot;Utilisation-Dobjets-Magiques.html&quot; title=&quot;Utilisation d&amp;#39;objets magiques&quot;&gt;Utilisation d’objets magiques&lt;/a&gt; +25, Vol +25&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues &lt;/b&gt;abyssal, a&#233;rien, aklo, c&#233;leste, draconique, ign&#233;, infernal, terreux&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;agile, ne respire pas, vol stellaire&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Du-N&#233;ant.html&quot; title=&quot;Dragon sid&#233;ral du n&#233;ant&quot;&gt;dragons du n&#233;ant&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Les cornes et les &#233;cailles d’&#233;b&#232;ne de ce dragon sont mouchet&#233;es d’une substance luisant d’une &#233;trange lumi&#232;re verte. Un ciel nocturne semble se refl&#233;ter dans les plis de ses ailes.&lt;/i&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
